var l=[{title:`Γιατί ο ύπνος μετράει για την προπόνηση`,text:`Ο ύπνος βοηθά στην επιδιόρθωση των ιστών, στη λειτουργία του νευρικού συστήματος, στην προσοχή και στην εκμάθηση κινητικών δεξιοτήτων. Μετά από κακό ύπνο ένα κανονικό φορτίο μπορεί να αισθάνεται βαρύτερο, και η κινητοποίηση ή ο συντονισμός σας μπορεί να πέσουν. Μία σύντομη νύχτα δεν σβήνει την πρόοδό σας, αλλά το να κόβετε τον ύπνο ξανά και ξανά μπορεί να βλάψει την ποιότητα της προπόνησης και τη γενική σας υγεία.`},{title:`Διάρκεια και ποιότητα`,text:`Οι οδηγίες δημόσιας υγείας συνιστούν επτά ή περισσότερες ώρες για ενήλικες ηλικίας 18–60 ετών, με εύρη ανά ηλικία μετά από αυτή. Τα συχνά ξυπνήματα, ένα ακανόνιστο πρόγραμμα ή το να μην αισθάνεστε ξεκούραστοι μπορούν να μετράνε ακόμη κι όταν ο χρόνος σας στο κρεβάτι φαίνεται αρκετός. Οι ανάγκες διαφέρουν, οπότε η σωστή ποσότητα είναι ατομική.`},{title:`Συνήθειες που βοηθούν`,text:`Πηγαίνετε για ύπνο και σηκώνεστε σε αρκετά σταθερές ώρες, κρατήστε την κρεβατοκάμαρα σκοτεινή και άνετη, περιορίστε το έντονο φως πριν από τον ύπνο και προσέξτε την καφεΐνη αργά. Το φως της ημέρας και η τακτική άσκηση μπορούν να βοηθήσουν να μένει προβλέψιμος ο ρυθμός του ύπνου σας. Μην κρίνετε τον ύπνο σας μόνο από μία βαθμολογία φορητής συσκευής.`},{title:`Προπόνηση μετά από κακή νύχτα`,text:`Μετά από μια ιδιαίτερα κακή νύχτα, αν η ισορροπία ή η συγκέντρωσή σας αισθάνεται εκτός, σκεφτείτε μια ελαφρύτερη συνεδρία τεχνικής, έναν ήπιο περίπατο ή μια μικρότερη προπόνηση. Μια περιστασιακή δύσκολη μέρα δεν είναι από μόνη της επικίνδυνη, αλλά το να αναγκάζετε μέγιστες ανυψώσεις ενώ είστε εξαντλημένοι ξανά και ξανά δεν σας κάνει καλό. Οι παρακολουθητές ύπνου δίνουν εκτιμήσεις, όχι κλινικές μετρήσεις. Αν έχετε συνεχή έντονη υπνηλία ή αϋπνία, μιλήστε σε γιατρό.`}];var i=[{label:`CDC: συστάσεις για τον ύπνο των ενηλίκων`,url:`https://www.cdc.gov/sleep/about/index.html/`},{label:`ACSM 2026: δοσολογία άσκησης, αποκατάσταση και πρόοδος`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};